void CreateNgrams(const tstring* data, tstring* output, int num_ngrams,
                  int ngram_width) const {
  for (int ngram_index = 0; ngram_index < num_ngrams; ++ngram_index) {
    int pad_width = get_pad_width(ngram_width);
    int left_padding = std::max(0, pad_width - ngram_index);
    int right_padding =
        std::max(0, pad_width - (num_ngrams - (ngram_index + 1)));
    int num_tokens = ngram_width - (left_padding + right_padding);
    int data_start_index = left_padding > 0 ? 0 : ngram_index - pad_width;

    // Calculate the total expected size of the ngram so we can reserve the
    // correct amount of space in the string.
    int ngram_size = 0;
    // Size of the left padding.
    ngram_size += left_padding * left_pad_.length();
    // Size of the tokens.
    for (int n = 0; n < num_tokens; ++n) {
      ngram_size += data[data_start_index + n].length();
    }
    // Size of the right padding.
    ngram_size += right_padding * right_pad_.length();
    // Size of the separators.
    int num_separators = left_padding + right_padding + num_tokens - 1;
    ngram_size += num_separators * separator_.length();

    // Build the ngram.
    tstring* ngram = &output[ngram_index];
    ngram->reserve(ngram_size);
    for (int n = 0; n < left_padding; ++n) {
      ngram->append(left_pad_);
      ngram->append(separator_);
    }
    for (int n = 0; n < num_tokens - 1; ++n) {
      ngram->append(data[data_start_index + n]);
      ngram->append(separator_);
    }
    ngram->append(data[data_start_index + num_tokens - 1]);
    for (int n = 0; n < right_padding; ++n) {
      ngram->append(separator_);
      ngram->append(right_pad_);
    }

    // In debug mode only: validate that we've reserved enough space for the
    // ngram.
    DCHECK_EQ(ngram_size, ngram->size());
  }
}

SWFInput_readSBits(SWFInput input, int number)
{
	int num = SWFInput_readBits(input, number);

	if ( num & (1<<(number-1)) )
		return num - (1<<number);
	else
		return num;
}

void CLASS foveon_load_camf()
{
  unsigned type, wide, high, i, j, row, col, diff;
  ushort huff[258], vpred[2][2] = {{512,512},{512,512}}, hpred[2];

  fseek (ifp, meta_offset, SEEK_SET);
  type = get4();  get4();  get4();
  wide = get4();
  high = get4();
  if (type == 2) {
    fread (meta_data, 1, meta_length, ifp);
    for (i=0; i < meta_length; i++) {
      high = (high * 1597 + 51749) % 244944;
      wide = high * (INT64) 301593171 >> 24;
      meta_data[i] ^= ((((high << 8) - wide) >> 1) + wide) >> 17;
    }
  } else if (type == 4) {
    free (meta_data);
    meta_data = (char *) malloc (meta_length = wide*high*3/2);
    merror (meta_data, "foveon_load_camf()");
    foveon_huff (huff);
    get4();
    getbits(-1);
    for (j=row=0; row < high; row++) {
      for (col=0; col < wide; col++) {
	diff = ljpeg_diff(huff);
	if (col < 2) hpred[col] = vpred[row & 1][col] += diff;
	else         hpred[col & 1] += diff;
	if (col & 1) {
	  meta_data[j++] = hpred[0] >> 4;
	  meta_data[j++] = hpred[0] << 4 | hpred[1] >> 8;
	  meta_data[j++] = hpred[1];
        }
      }
    }
  } else
    fprintf (stderr,_("%s has unknown CAMF type %d.\n"), ifname, type);
}

void CLASS foveon_dp_load_raw()
{
  unsigned c, roff[4], row, col, diff;
  ushort huff[512], vpred[2][2], hpred[2];

  fseek (ifp, 8, SEEK_CUR);
  foveon_huff (huff);
  roff[0] = 48;
  FORC3 roff[c+1] = -(-(roff[c] + get4()) & -16);
  FORC3 {
    fseek (ifp, data_offset+roff[c], SEEK_SET);
    getbits(-1);
    vpred[0][0] = vpred[0][1] = vpred[1][0] = vpred[1][1] = 512;
    for (row=0; row < height; row++) {
#ifdef LIBRAW_LIBRARY_BUILD
    checkCancel();
#endif
      for (col=0; col < width; col++) {
	diff = ljpeg_diff(huff);
	if (col < 2) hpred[col] = vpred[row & 1][col] += diff;
	else hpred[col & 1] += diff;
	image[row*width+col][c] = hpred[col & 1];
      }
    }
  }
}

void ComputeAsync(OpKernelContext* c, DoneCallback done) override {
  auto col_params = new CollectiveParams();
  auto done_with_cleanup = [col_params, done = std::move(done)]() {
    done();
    col_params->Unref();
  };
  core::RefCountPtr<CollectiveGroupResource> resource;
  OP_REQUIRES_OK_ASYNC(c, LookupResource(c, HandleFromInput(c, 1), &resource),
                       done);

  Tensor group_assignment = c->input(2);

  OP_REQUIRES_OK_ASYNC(
      c,
      FillCollectiveParams(col_params, group_assignment,
                           ALL_TO_ALL_COLLECTIVE, resource.get()),
      done);
  col_params->instance.shape = c->input(0).shape();
  VLOG(1) << "CollectiveAllToAll group_size " << col_params->group.group_size
          << " group_key " << col_params->group.group_key << " instance_key "
          << col_params->instance.instance_key;
  // Allocate the output tensor, trying to reuse the input.
  Tensor* output = nullptr;
  OP_REQUIRES_OK_ASYNC(c,
                       c->forward_input_or_allocate_output(
                           {0}, 0, col_params->instance.shape, &output),
                       done_with_cleanup);
  Run(c, col_params, std::move(done_with_cleanup));
}

Status CheckInputs(Tensor group_size_t, Tensor group_key_t) {
  if (group_size_t.dims() > 0) {
    return errors::Internal(
        "Unexpected dimensions on input group_size. "
        "It shoulbe a scalar, got tensor with shape ",
        group_size_t.shape().DebugString());
  }
  if (group_key_t.dims() > 0) {
    return errors::Internal("Unexpected dimensions on input group_key, got ",
                            group_key_t.shape().DebugString());
  }

  auto group_size = group_size_t.unaligned_flat<int32>()(0);
  if (group_size <= 0) {
    return errors::InvalidArgument(
        "group_size must be positive integer but got ", group_size);
  }
  return Status::OK();
}

